ZEND_METHOD(Gtk4_GDBusProxy, get_interface_info) {
  ZEND_PARSE_PARAMETERS_NONE();
  GDBusProxy *self = PHPGTK_SELF(GDBusProxy, G_TYPE_DBUS_PROXY);
  GDBusInterfaceInfo *phpgtk_ret = g_dbus_proxy_get_interface_info(self);
  wrap_boxed(G_TYPE_DBUS_INTERFACE_INFO, phpgtk_ret, return_value);
}

